class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        top = max(nums)
        best = [None] * (top + 1)
        seen = []
        answer = 1
        for x in nums:
            cur = [1] * top
            for v in seen:
                d = abs(x - v)
                val = best[v][d] + 1
                if val > cur[d]:
                    cur[d] = val
