class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        if len(nums) <= 3:
            return len(nums)
        top = max(nums)
        best = [None] * (top + 1)
        seen = []
        answer = 1
        for x in nums:
            cur = [1] * top
            for v in seen:
